Okay nice. Here is the save script call I use
try {
// Set saving flag
$gameTemp.saving = true;
// Ensure game state is prepared
$gameSystem.onBeforeSave();
// Introduce a short delay to ensure all processes are stable
setTimeout(() => {
// Perform the save operation
DataManager.saveGame(2).then(function (success) {
if (success) {
console.log("Game saved successfully in slot 2.");
} else {
console.error("Failed to save game.");
}
}).catch(function (error) {
console.error("Error during save operation:", error);
}).finally(function () {
// Clear saving flag
delete $gameTemp.saving;
});
}, 100); // 100ms delay
} catch (error) {
console.error("Unexpected error during save preparation:", error);
}
